const fs = require('node:fs');
const path = require('node:path');
const config = require('../config');
const db = require('../database');
const { logActivityStrict } = require('../helpers/activity');
const { existingUploadPath } = require('./uploadPaths');

// Only receives a filename generated by Multer for THIS request, never an old
// catalog path. A failed response after commit must not delete its saved image.
function discardNewUpload(filename) {
  if (!filename || !/^[0-9a-f-]{36}\.[a-z0-9]+$/i.test(filename)) return;
  try {
    const names = [filename, `/uploads/${filename}`];
    const referenced = db.prepare(`
      SELECT 1 FROM collections WHERE image_path IN (?, ?)
      UNION ALL SELECT 1 FROM questions WHERE image_path IN (?, ?)
      UNION ALL SELECT 1 FROM materials WHERE file_path IN (?, ?) OR thumbnail_path IN (?, ?)
      UNION ALL SELECT 1 FROM class_assessment_items WHERE image_path_snapshot IN (?, ?)
      UNION ALL SELECT 1 FROM material_file_retirements WHERE file_path IN (?, ?)
      UNION ALL SELECT 1 FROM material_draft_files WHERE file_path IN (?, ?)
      LIMIT 1
    `).get(...names, ...names, ...names, ...names, ...names, ...names, ...names);
    if (referenced) return;
    const candidate = path.join(config.uploadDir, filename);
    if (!fs.existsSync(candidate) || fs.lstatSync(candidate).isSymbolicLink()) return;
    const resolved = existingUploadPath(filename);
    if (resolved) fs.unlinkSync(resolved);
  } catch {
    // Fail safe: keep the file if checking references or cleanup fails.
    console.error('Não foi possível limpar um upload novo; arquivo preservado para conferência.');
  }
}

// Uses the existing, admin-only audit store. No public recovery endpoint and no
// physical deletion: assessment snapshots/shared references keep their image.
// Call BEFORE changing the row, inside the same transaction as its main audit.
function preservePreviousImage(req, entityType, previous, nextPath, reason) {
  if (!previous.image_path || previous.image_path === nextPath) return;
  if (!db.inTransaction) throw new Error('Image preservation requires a transaction.');
  if (!['collection', 'question'].includes(entityType)
      || !['replaced', 'removed', 'deleted'].includes(reason)) {
    throw new Error('Invalid image preservation context.');
  }
  const relatedRows = entityType === 'collection'
    ? { collection_items: db.prepare('SELECT * FROM collection_items WHERE collection_id = ?').all(previous.id) }
    : { question_options: db.prepare('SELECT * FROM question_options WHERE question_id = ? ORDER BY sort_order, id').all(previous.id) };
  logActivityStrict({
    user: req.user,
    action: `preserve_${entityType}_image`,
    module: entityType === 'collection' ? 'collections' : 'question_bank',
    entityType,
    entityId: previous.id,
    entityTitle: previous.name || previous.question_code,
    description: 'Imagem anterior preservada para referências existentes e recuperação técnica.',
    metadata: {
      version: 1, reason, file_path: previous.image_path, replacement_path: nextPath || null,
      recovery: { previous, relatedRows },
    },
    req,
  });
}

module.exports = { discardNewUpload, preservePreviousImage };
